// src/lib/data/cache.ts
import { cache } from 'react';

// Cache user data for request duration
export const getCachedUser = cache(async (userId: number) => {
  const response = await fetch(`${process.env.API_URL}/api/users/${userId}`, {
    credentials: 'include',
  });

  if (!response.ok) {
    throw new Error('Failed to fetch user');
  }

  return response.json();
});

// Cache dashboard data
export const getCachedDashboard = cache(async (role: string, userId: number) => {
  const response = await fetch(
    `${process.env.API_URL}/api/${role}/dashboard`,
    { credentials: 'include' }
  );

  if (!response.ok) {
    throw new Error('Failed to fetch dashboard');
  }

  return response.json();
});

// Parallel fetching example
export async function getDashboardData(userId: number, role: string) {
  const [user, dashboard, periods] = await Promise.all([
    getCachedUser(userId),
    getCachedDashboard(role, userId),
    getCachedPeriods(),
  ]);

  return { user, dashboard, periods };
}
